DevExpress.XtraPrinting.BorderSide bordersTopBottomRight  = ((DevExpress.XtraPrinting.BorderSide)(((DevExpress.XtraPrinting.BorderSide.Top | DevExpress.XtraPrinting.BorderSide.Right) 
            | DevExpress.XtraPrinting.BorderSide.Bottom)));
private void xrTable1_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if(GetCurrentColumnValue("K1") != null )
 {
	int kodi = Convert.ToInt32(GetCurrentColumnValue("K1").ToString());
	if(kodi == 200 || kodi == 700 || kodi == 910)
  {
		xrTable1.TopF = 40;
		Detail.HeightF = 80;
  }	
      else 
  {
		xrTable1.TopF = 0;
		Detail.HeightF = 40;

  }
 }
}

private void xrTableCell5_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if(GetCurrentColumnValue("K1") != null )
 {
	int kodi = Convert.ToInt32(GetCurrentColumnValue("K1").ToString());
	if(kodi == 400 )
		((XRTableCell)sender).Text = GetCurrentColumnValue("K10").ToString();//adrese1 kf
	else
		((XRTableCell)sender).Text = GetCurrentColumnValue("K6").ToString();
	hideBorders200300(sender, e);
} 
}

