private void xrTableCell11_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
if(GetCurrentColumnValue("K1") != null )
 {

int kodi = Convert.ToInt32(GetCurrentColumnValue("K1").ToString());
	if(kodi == 400)
		((XRTableCell)sender).Text = "";//adrese3 kf
	else
		((XRTableCell)sender).Text = GetCurrentColumnValue("K12").ToString();

	hideBorders(sender, e);
}
}

private void xrTableCell12_BeforePrint(object sender, System.Drawing.Printing.PrintEventArgs e) {
	hideBorders(sender, e);
}

private void hideBorders(object sender, System.Drawing.Printing.PrintEventArgs e) {
if(GetCurrentColumnValue("K1") != null )
 {

	int kodi = Convert.ToInt32(GetCurrentColumnValue("K1").ToString());
	if(kodi == 510)
		((XRTableCell)sender).Borders = bordersTopBottomRight;
	else
		((XRTableCell)sender).Borders = BorderSide.None;	
}
}

private void hideBorders200300(object sender, System.Drawing.Printing.PrintEventArgs e) {
if(GetCurrentColumnValue("K1")!= null )
 {

	int kodi = Convert.ToInt32(GetCurrentColumnValue("K1").ToString());
	if(kodi == 200 || kodi == 300 || kodi == 700)
		((XRTableCell)sender).Borders = BorderSide.None;
	else
		((XRTableCell)sender).Borders =bordersTopBottomRight ;
}	
}




